using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Studio {
 static GlbModel TestCube(){return GlbModel.Load(File.ReadAllBytes(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Sample 3D cube.glb")));}
 public void TestVersion40(){TestGLBVariants();var model=TestCube();if(model.Vertices.Length!=24||model.Triangles.Length!=12||model.Textures.Count!=1||model.Materials[0].Texture!=0)throw new Exception("GLB geometry/material/texture import");if(model.Vertices.Any(v=>v.P.Length()>1.001f)||Math.Abs(model.Vertices.Average(v=>v.P.X))>.001)throw new Exception("GLB node transform and centring");bool rejected=false;try{GlbModel.Load(new byte[40]);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Invalid GLB rejection");
 SetDocument(new Document("A4",100),null);AddThreeDModel(model,"test cube");canvas.Zoom=1;canvas.Offset=PointF.Empty;var layer=canvas.Doc.Selected;if(!layer.Is3D||layer.IsRaster||layer.IsVector||pixelControls.Any(c=>c.Visible)||vectorControls.Any(c=>c.Visible)||!threeDOrbit.Visible)throw new Exception("Third layer type and contextual controls");var view=layer.Scene;float initialYaw=view.Yaw;var before=Document.Png(layer.Rendered());if(layer.Rendered().GetPixel((int)view.X,(int)view.Y).A==0)throw new Exception("3D raster output empty");int history=undo.Count;canvas.TestDrag(new Point(400,300),new Point(460,330));if(Math.Abs(layer.Scene.Yaw-initialYaw-36)>.01||undo.Count!=history+1||Document.Png(layer.Rendered()).SequenceEqual(before))throw new Exception("3D orbit rendering / undo record");Travel(undo,redo);if(!Document.Png(layer.Rendered()).SequenceEqual(before))throw new Exception("Orbit undo");Travel(redo,undo);view=layer.Scene;float x=view.X,y=view.Y;canvas.Move3D=true;canvas.TestDrag(new Point(400,300),new Point(440,330));if(Math.Abs(layer.Scene.X-x-40)>.01||Math.Abs(layer.Scene.Y-y-30)>.01)throw new Exception("3D page positioning");float scale=layer.Scene.Scale;canvas.TestThreeDWheel(120);if(layer.Scene.Scale<=scale)throw new Exception("3D wheel zoom");canvas.ResetThreeD();if(layer.Scene.Scale!=1||layer.Scene.X!=canvas.Doc.Width/2f)throw new Exception("3D reset");
 layer.Locked=true;history=undo.Count;float yaw=layer.Scene.Yaw;canvas.TestDrag(new Point(300,300),new Point(500,400));canvas.SetThreeDZoom(2);canvas.FillAt(new PointF(100,100));FillLayer();ClearLayer();if(undo.Count!=history||layer.Scene.Scale!=1||layer.Scene.Yaw!=yaw||layer.Image.GetPixel(100,100).A!=0)throw new Exception("Locked 3D / pixel edit guards");layer.Locked=false;
 DuplicateLayer();var copy=canvas.Doc.Selected;if(!copy.Is3D||ReferenceEquals(copy.Scene,layer.Scene)||!ReferenceEquals(copy.Scene.Model,layer.Scene.Model))throw new Exception("3D duplicate independent view / shared immutable asset");copy.Scene.Yaw+=30;copy.InvalidateVectors();if(copy.Scene.Yaw==layer.Scene.Yaw)throw new Exception("3D copy view independence");copy.Visible=false;canvas.Doc.Active=canvas.Doc.Layers.IndexOf(layer);RefreshLayers();using(var graphics=Graphics.FromImage(canvas.Doc.Layers[0].Image))graphics.FillRectangle(Brushes.Red,10,10,30,30);canvas.Doc.Layers[0].InvalidateVectors();var vectorOverlay=new Layer("Capture vector test",canvas.Doc.Width,canvas.Doc.Height){IsVector=true};vectorOverlay.Vectors.Add(new VectorShape{Kind="Line",Colour=Color.Blue,Width=8,Points=new System.Collections.Generic.List<PointF>{new PointF(50,50),new PointF(200,50)}});canvas.Doc.Layers.Add(vectorOverlay);byte[] expected;using(var image=canvas.Doc.Flatten())expected=Document.Png(image);int count=canvas.Doc.Layers.Count;CaptureCanvasLayer();var snapshot=canvas.Doc.Layers.Last();if(canvas.Doc.Layers.Count!=count+1||snapshot.Is3D||!snapshot.IsRaster||snapshot.Visible||canvas.Doc.Selected!=layer||!Document.Png(snapshot.Image).SequenceEqual(expected))throw new Exception("Canvas screenshot layer / visibility / full-resolution content");if(snapshot.Image.GetPixel(20,20).R!=255||snapshot.Image.GetPixel(100,50).B!=255)throw new Exception("Capture includes pixel and vector artwork");if(snapshot.Image.Size!=layer.Image.Size||Math.Abs(snapshot.Image.HorizontalResolution-canvas.Doc.Dpi)>.1)throw new Exception("Screenshot dimensions / DPI");
 string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file)){var models=loaded.Layers.Where(l=>l.Is3D).ToArray();if(models.Length!=2)throw new Exception("3D layer count persistence");if(models[0].Scene.Model.Triangles.Length!=12)throw new Exception("3D geometry persistence");if(models[1].Scene.Yaw!=copy.Scene.Yaw)throw new Exception("3D yaw persistence");if(!models[0].Scene.Model.Source.SequenceEqual(model.Source))throw new Exception("GLB bytes persistence");if(!HistoryItem.Capture(loaded.Layers.Last().Image).SequenceEqual(HistoryItem.Capture(snapshot.Image)))throw new Exception("Snapshot pixel persistence");using(var flat=loaded.Flatten())if(!Document.Png(flat).SequenceEqual(expected))throw new Exception("Reopened 3D output");}}finally{File.Delete(file);}dirty=false;}
 static byte[] RewriteGLB(byte[] original,Action<System.Collections.Generic.Dictionary<string,object>> change){int jsonLength=BitConverter.ToInt32(original,12);var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();var root=(System.Collections.Generic.Dictionary<string,object>)serializer.DeserializeObject(System.Text.Encoding.UTF8.GetString(original,20,jsonLength));change(root);byte[] json=System.Text.Encoding.UTF8.GetBytes(serializer.Serialize(root));int padded=(json.Length+3)/4*4,binStart=20+jsonLength;using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(0x46546c67);writer.Write(2);writer.Write(20+padded+original.Length-binStart);writer.Write(padded);writer.Write(0x4e4f534a);writer.Write(json);for(int i=json.Length;i<padded;i++)writer.Write((byte)32);writer.Write(original,binStart,original.Length-binStart);return stream.ToArray();}}
 static void TestGLBVariants(){var original=TestCube().Source;bool rejected=false;try{GlbModel.Load(RewriteGLB(original,root=>root["extensionsRequired"]=new object[]{"KHR_draco_mesh_compression"}));}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Compressed GLB rejection");var mirrored=GlbModel.Load(RewriteGLB(original,root=>((System.Collections.Generic.Dictionary<string,object>)((object[])root["nodes"])[1])["scale"]=new object[]{-1,2,1}));if(mirrored.Triangles[0].B!=TestCube().Triangles[0].C||mirrored.Vertices.Max(v=>v.P.Y)<=mirrored.Vertices.Max(v=>v.P.X))throw new Exception("Mirrored winding and nonuniform node scale");
 var model=TestCube();foreach(var material in model.Materials){material.Unlit=true;material.DoubleSided=true;material.Texture=-1;material.R=0;material.G=0;material.B=1;}model.Materials[0].R=1;model.Materials[0].B=0;var view=new ThreeDView{Model=model,X=100,Y=100,Yaw=0,Pitch=0,FullQuality=true};using(var image=view.Render(200,200))if(image.GetPixel(100,100).R<250||image.GetPixel(100,100).B>5)throw new Exception("3D depth occlusion");model.Triangles=model.Triangles.Where(t=>t.Material==0).ToArray();model.Materials[0].Alpha="BLEND";model.Materials[0].A=.5f;using(var image=view.Render(200,200))if(image.GetPixel(100,100).A<120||image.GetPixel(100,100).A>135||image.GetPixel(0,0).A!=0)throw new Exception("GLB material alpha / transparent background");
 }
 public void PreviewThreeD(){SetDocument(new Document(CanvasPreset.All[0]),null);AddThreeDModel(TestCube(),"Textured cube");canvas.Fit();toolPanel.AutoScrollPosition=Point.Empty;using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"3d-layer-preview.png"));}using(var full=canvas.Doc.Flatten())full.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"3d-canvas-capture.png"));dirty=false;}
}
